// Copies contracts/ops/project.schema.json next to its readers and generates web/src/store/schema.gen.ts.
// Usage: node scripts/gen-ops-schema.mjs [--check]
// --check writes nothing and exits 1 when a generated file is stale.
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const canonical = 'contracts/ops/project.schema.json'

const header =
  '// Code generated by scripts/gen-ops-schema.mjs from contracts/ops/project.schema.json. DO NOT EDIT.\n'

function pascal(name) {
  return name
    .split('_')
    .map((p) => p.charAt(0).toUpperCase() + p.slice(1))
    .join('')
}

function sorted(obj) {
  return Object.keys(obj).sort()
}

function fieldType(f) {
  let t
  switch (f.type) {
    case 'string':
    case 'ref':
    case 'external_ref':
      t = 'string'
      break
    case 'int':
    case 'number':
      t = 'number'
      break
    case 'bool':
      t = 'boolean'
      break
    case 'enum':
      t = f.values.map((v) => `'${v}'`).join(' | ')
      break
    case 'point':
      t = 'Point'
      break
    case 'points':
      t = 'Point[]'
      break
    case 'object':
      t = 'unknown'
      break
    case 'params':
      t = 'Record<string, unknown>'
      break
    case 'ref_list':
      t = 'string[]'
      break
    default:
      throw new Error(`unknown field type ${f.type}`)
  }
  if (f.nullable && t !== 'unknown') {
    t = `${t} | null`
  }
  return t
}

// generateTypes returns schema.gen.ts for a parsed schema.
export function generateTypes(schema) {
  const names = sorted(schema.collections)
  const out = [header]
  out.push(`export const schemaVersion = ${schema.version}`, '')
  out.push('export type Point = { x: number; y: number }', '')
  const singletons = names.filter((n) => schema.collections[n].kind === 'singleton')
  const lists = names.filter((n) => schema.collections[n].kind === 'list')
  const ordered = names.filter((n) => schema.collections[n].ordered)
  for (const name of names) {
    const c = schema.collections[name]
    const fields = sorted(c.fields)
    out.push(`export type ${pascal(name)}Record = {`)
    out.push('  id: string')
    if (c.ordered) {
      out.push('  order: string')
    }
    for (const fn of fields) {
      out.push(`  ${fn}: ${fieldType(c.fields[fn])}`)
    }
    out.push('}', '')
    if (c.kind === 'list') {
      out.push(`export type ${pascal(name)}Insert = {`)
      if (c.ordered) {
        out.push('  order: string')
      }
      for (const fn of fields) {
        const f = c.fields[fn]
        out.push(`  ${fn}${f.required ? '' : '?'}: ${fieldType(f)}`)
      }
      out.push('}', '')
    }
  }
  out.push('export type Records = {')
  for (const name of names) {
    out.push(`  ${name}: ${pascal(name)}Record`)
  }
  out.push('}', '')
  out.push('export type Inserts = {')
  for (const name of lists) {
    out.push(`  ${name}: ${pascal(name)}Insert`)
  }
  out.push('}', '')
  out.push('export type CollectionName = keyof Records')
  out.push(`export type SingletonName = ${singletons.map((n) => `'${n}'`).join(' | ')}`)
  out.push('export type ListName = keyof Inserts')
  out.push(`export type OrderedName = ${ordered.map((n) => `'${n}'`).join(' | ')}`)
  out.push('')
  out.push('export type KeyedField = {')
  for (const name of names) {
    const c = schema.collections[name]
    const keyed = sorted(c.fields).filter((fn) => ['object', 'params'].includes(c.fields[fn].type))
    out.push(`  ${name}: ${keyed.length ? keyed.map((k) => `'${k}'`).join(' | ') : 'never'}`)
  }
  out.push('}', '')
  out.push('export type SetPath<C extends CollectionName> = Exclude<keyof Records[C], \'id\' | \'order\'> | `${KeyedField[C]}.${string}`')
  out.push('')
  out.push('export type Op =')
  out.push('  | { [C in ListName]: { op: \'insert\'; coll: C; id: string; value: Inserts[C] } }[ListName]')
  out.push('  | { [C in CollectionName]: { op: \'set\'; coll: C; id?: string; path: SetPath<C>; value: unknown } }[CollectionName]')
  out.push('  | { op: \'delete\'; coll: ListName; id: string }')
  out.push('  | { op: \'move\'; coll: OrderedName; id: string; order: string }')
  out.push('')
  return out.join('\n')
}

export function outputs(text) {
  const schema = JSON.parse(text)
  return {
    'api/internal/ops/project.schema.json': text,
    'web/src/store/project.schema.json': text,
    'web/src/store/schema.gen.ts': generateTypes(schema),
  }
}

function read(path) {
  try {
    return readFileSync(join(root, path), 'utf8')
  } catch {
    return null
  }
}

function main() {
  const check = process.argv.includes('--check')
  const files = outputs(read(canonical))
  const stale = []
  for (const [path, content] of Object.entries(files)) {
    if (read(path) === content) {
      continue
    }
    if (check) {
      stale.push(path)
    } else {
      writeFileSync(join(root, path), content)
    }
  }
  if (stale.length) {
    console.error(`stale generated files, run node scripts/gen-ops-schema.mjs:\n${stale.join('\n')}`)
    process.exit(1)
  }
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  main()
}
